#!/usr/bin/env python3
from __future__ import annotations

import inspect
import platform
import sys
import types
from pathlib import Path


def _run_impl(source: str, impl_name: str) -> int:
    module_name = f'{__name__}.{impl_name}'
    module = types.ModuleType(module_name)
    module.__file__ = str(Path(__file__).resolve())
    sys.modules[module_name] = module
    namespace = module.__dict__
    exec(compile(source, str(Path(__file__).resolve()), 'exec'), namespace, namespace)
    main_fn = namespace.get('main')
    if not callable(main_fn):
        raise RuntimeError(f"Selected implementation '{impl_name}' for 'sys_config' does not define main()")
    sig = inspect.signature(main_fn)
    if len(sig.parameters) == 0:
        return int(main_fn())
    if len(sig.parameters) == 1:
        return int(main_fn(sys.argv))
    raise RuntimeError(f"Selected implementation '{impl_name}' for 'sys_config' has unsupported main() signature")


def main() -> int:
    if platform.system().strip().lower().startswith('win'):
        return _run_impl(_WINDOWS_IMPL, 'windows')
    return _run_impl(_LINUX_IMPL, 'linux')


_LINUX_IMPL = 'from __future__ import annotations\n\nimport re\nimport subprocess\nfrom pathlib import Path\n\nfrom _linux_common import CONFIG_FILE, load_config, resolve_path, run_capture, shell_exists\n\n\ndef _run_text(cmd: list[str]) -> str:\n\trc, out = run_capture(cmd)\n\tif rc != 0:\n\t\treturn ""\n\treturn out.strip()\n\n\ndef _driver_meta(module: str) -> list[str]:\n\tif not module:\n\t\treturn []\n\trc, out = run_capture(["modinfo", module])\n\tif rc != 0 or not out:\n\t\treturn [f"  > Driver: {module}"]\n\n\tlines = [f"  > Driver: {module}"]\n\tfor ln in out.splitlines():\n\t\tif ln.startswith("version:") or ln.startswith("description:") or ln.startswith("srcversion:"):\n\t\t\tlines.append(f"    {ln}")\n\treturn lines\n\n\ndef _detect_ov_version(ov_root: Path) -> str:\n\tversion_file = ov_root / "runtime" / "version.txt"\n\tif version_file.is_file():\n\t\ttxt = version_file.read_text(encoding="utf-8", errors="ignore").splitlines()\n\t\tif txt:\n\t\t\treturn txt[0].strip() or "N/A"\n\treturn "N/A"\n\n\ndef _resolve_ov_config() -> tuple[int, str, Path | None]:\n\tif not CONFIG_FILE.is_file():\n\t\treturn 1, "", None\n\n\tcfg = load_config()\n\tov_cfg = cfg.get("openvino") or {}\n\tov_mode = str(ov_cfg.get("version", "")).strip().lower()\n\tif ov_mode not in {"default", "latest"}:\n\t\treturn 2, "", None\n\n\tov_dest_raw = cfg.get("llamacpp_ov_dir")\n\tif not ov_dest_raw:\n\t\treturn 3, "", None\n\n\treturn 0, ov_mode.upper(), resolve_path(str(ov_dest_raw))\n\n\ndef main() -> int:\n\tprint("=== OS & KERNEL ===")\n\tdesc = _run_text(["lsb_release", "-d"])\n\tif "\\t" in desc:\n\t\tdesc = desc.split("\\t", 1)[1].strip()\n\tprint(desc or "N/A")\n\tprint(_run_text(["uname", "-r"]) or "N/A")\n\n\tprint("\\n=== SYSTEM HARDWARE ===")\n\tmodel = Path("/sys/class/dmi/id/product_name")\n\tmodel_name = model.read_text(encoding="utf-8", errors="ignore").strip() if model.is_file() else "N/A"\n\tcpu_txt = _run_text(["lscpu"])\n\tcpu_name = "N/A"\n\tfor ln in cpu_txt.splitlines():\n\t\tif "Model name:" in ln:\n\t\t\tcpu_name = ln.split("Model name:", 1)[1].strip()\n\t\t\tbreak\n\tmem_txt = _run_text(["free", "-h"])\n\tmem = "N/A"\n\tfor ln in mem_txt.splitlines():\n\t\tif ln.startswith("Mem:"):\n\t\t\tparts = ln.split()\n\t\t\tif len(parts) > 1:\n\t\t\t\tmem = parts[1]\n\t\t\tbreak\n\n\tprint(f"Model: {model_name}")\n\tprint(f"CPU: {cpu_name}")\n\tprint(f"Memory: {mem}")\n\tif shell_exists("df"):\n\t\tdf_txt = _run_text(["df", "-h", "/"]).splitlines()\n\t\tif len(df_txt) >= 2:\n\t\t\tstorage_total = df_txt[1].split()[1]\n\t\t\tprint(f"Storage : {storage_total}")\n\t\telse:\n\t\t\tprint("Storage : N/A")\n\telse:\n\t\tprint("Storage : N/A")\n\n\tprint("\\n=== GPU DETAILS ===")\n\tif shell_exists("nvidia-smi"):\n\t\tprint(_run_text(["nvidia-smi", "--query-gpu=name,driver_version", "--format=csv,noheader"]) or "N/A")\n\t\tfor ln in _driver_meta("nvidia"):\n\t\t\tprint(ln)\n\telse:\n\t\tlspci_k = _run_text(["lspci", "-k"])\n\t\tgpu_driver = ""\n\t\tblocks = lspci_k.splitlines()\n\t\tfor idx, ln in enumerate(blocks):\n\t\t\tif "VGA" in ln:\n\t\t\t\tfor sub in blocks[idx: idx + 4]:\n\t\t\t\t\tif "Kernel driver in use:" in sub:\n\t\t\t\t\t\tgpu_driver = sub.split(":", 1)[1].strip()\n\t\t\t\tbreak\n\n\t\tlspci_nnk = _run_text(["lspci", "-nnk"])\n\t\tfor idx, ln in enumerate(lspci_nnk.splitlines()):\n\t\t\tif "VGA" in ln:\n\t\t\t\tprint(ln)\n\t\t\t\t# Print nearby lines for kernel driver details.\n\t\t\t\tnxt = lspci_nnk.splitlines()[idx + 1: idx + 4]\n\t\t\t\tfor sub in nxt:\n\t\t\t\t\tif "kernel driver" in sub.lower():\n\t\t\t\t\t\tprint(sub)\n\t\t\t\tbreak\n\n\t\tfor ln in _driver_meta(gpu_driver):\n\t\t\tprint(ln)\n\t\tprint("  > API Version:")\n\t\trc, glx = run_capture(["glxinfo", "-B"])\n\t\tif rc == 0 and glx:\n\t\t\tfor ln in glx.splitlines():\n\t\t\t\tif "Device:" in ln or re.match(r"\\s*Version:", ln):\n\t\t\t\t\tprint(f"    {ln.strip()}")\n\t\telse:\n\t\t\tprint("    [Install \'mesa-utils\' for GL info]")\n\n\tprint("\\n=== NPU DETAILS ===")\n\tlsmod = _run_text(["lsmod"])\n\tnpu_module = ""\n\tfor ln in lsmod.splitlines():\n\t\tif re.search(r"intel_vpu|vpu|accel|amd_npu", ln, flags=re.IGNORECASE):\n\t\t\tnpu_module = ln.split()[0]\n\t\t\tbreak\n\n\tif npu_module:\n\t\tprint("NPU Status: Active")\n\t\tfor ln in _driver_meta(npu_module):\n\t\t\tprint(ln)\n\telif shell_exists("nputop"):\n\t\tprint("NPU Status: Tool \'nputop\' found, but module not detected in lsmod.")\n\telse:\n\t\tlspci = _run_text(["lspci", "-nn"])\n\t\tnpu_hits = [ln for ln in lspci.splitlines() if re.search(r"AI|Accelerator|Neural|NPU", ln, flags=re.IGNORECASE)]\n\t\tif npu_hits:\n\t\t\tprint("Hardware Found (Driver potentially missing):")\n\t\t\tfor ln in npu_hits:\n\t\t\t\tprint(f"  {ln}")\n\t\t\tlspci_k = _run_text(["lspci", "-k"])\n\t\t\tdrv = ""\n\t\t\tlines = lspci_k.splitlines()\n\t\t\tfor idx, ln in enumerate(lines):\n\t\t\t\tif re.search(r"AI|Accelerator|Neural", ln, flags=re.IGNORECASE):\n\t\t\t\t\tfor sub in lines[idx: idx + 4]:\n\t\t\t\t\t\tif "Kernel driver in use:" in sub:\n\t\t\t\t\t\t\tdrv = sub.split(":", 1)[1].strip()\n\t\t\t\t\t\t\tbreak\n\t\t\tfor ln in _driver_meta(drv):\n\t\t\t\tprint(ln)\n\t\telse:\n\t\t\tprint("NPU Status: Not detected.")\n\n\tprint("\\n=== OPENVINO DETAILS ===")\n\tstatus, ov_mode, ov_dest = _resolve_ov_config()\n\tif status == 1:\n\t\tprint(f"OpenVINO Config: Missing config file at {CONFIG_FILE}")\n\telif status == 2:\n\t\tprint("OpenVINO Config Error: openvino.version must be \'default\' or \'latest\'")\n\telif status == 3:\n\t\tprint("OpenVINO Config Error: Missing llamacpp_ov_dir")\n\telse:\n\t\tassert ov_dest is not None\n\t\tprint(f"Configured Mode: {ov_mode}")\n\t\tprint(f"Configured Location: {ov_dest}")\n\t\tsetupvars = ov_dest / "setupvars.sh"\n\t\tif setupvars.is_file():\n\t\t\tprint("Setupvars: Found")\n\t\t\tprint(f"OpenVINO Version: {_detect_ov_version(ov_dest)}")\n\t\telse:\n\t\t\tprint(f"Setupvars: Missing ({setupvars})")\n\t\t\tprint("OpenVINO Version: N/A")\n\n\treturn 0\n\n\nif __name__ == "__main__":\n\traise SystemExit(main())\n'


_WINDOWS_IMPL = 'from __future__ import annotations\n\nimport os\nimport platform\nimport subprocess\nfrom pathlib import Path\n\nfrom _windows_common_ import dependency_root, load_config, project_root\n\n\ndef ps(cmd: str) -> str:\n    p = subprocess.run(\n        ["powershell.exe", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", cmd],\n        capture_output=True,\n        text=True,\n    )\n    return (p.stdout or "").strip()\n\n\ndef main() -> int:\n    root = project_root(__file__)\n    cfg = load_config(root)\n    dep = dependency_root(root, cfg)\n    ov_root = dep / "openvino"\n\n    print("=== OS ===")\n    os_details = ps(\n        "$os = Get-CimInstance Win32_OperatingSystem; "\n        "if (-not $os) { \'\' } else { "\n        "$out = @(); "\n        "$out += \\"Platform: {0}\\" -f [System.Environment]::OSVersion.VersionString; "\n        "$out += \\"Caption: $($os.Caption)\\"; "\n        "$out += \\"Version: $($os.Version)\\"; "\n        "$out += \\"BuildNumber: $($os.BuildNumber)\\"; "\n        "$out += \\"Architecture: $($os.OSArchitecture)\\"; "\n        "$out -join [Environment]::NewLine }"\n    )\n    print(os_details or platform.platform())\n    print()\n\n    print("=== CPU ===")\n    cpu_query = """\n$cs = Get-CimInstance Win32_ComputerSystem\n$cpu = Get-CimInstance Win32_Processor | Select-Object -First 1\n$bb = Get-CimInstance Win32_BaseBoard | Select-Object -First 1\n\nif (-not $cpu) {\n    \'\'\n} else {\n    $out = @()\n    if ($cs) {\n        $out += "SystemModel: $($cs.Model)"\n        $out += "SystemType: $($cs.SystemType)"\n        $out += "SystemSKU: $($cs.SystemSKUNumber)"\n    }\n\n    $procSummary = "$($cpu.Name), $($cpu.MaxClockSpeed) Mhz, $($cpu.NumberOfCores) Core(s), $($cpu.NumberOfLogicalProcessors) Logical Processor(s)"\n    $out += "Processor: $procSummary"\n    $out += "ProcessorManufacturer: $($cpu.Manufacturer)"\n    $out += "ProcessorId: $($cpu.ProcessorId)"\n\n    if ($bb) {\n        $out += "BaseBoardManufacturer: $($bb.Manufacturer)"\n        $out += "BaseBoardProduct: $($bb.Product)"\n    }\n\n    $out -join [Environment]::NewLine\n}\n"""\n    cpu_details = ps(cpu_query)\n    print(cpu_details or (platform.processor() or "Unknown"))\n    print()\n\n    print("=== GPU DETAILS ===")\n    gpu = ps(\n        "$rows = Get-CimInstance Win32_VideoController | Select-Object Name,DriverVersion; "\n        "if (-not $rows) { \'\' } else { "\n        "$out = @(); "\n        "foreach ($r in $rows) { "\n        "$out += \\"Name: $($r.Name)\\"; "\n        "$out += \\"DriverVersion: $($r.DriverVersion)\\"; "\n        "$out += \'\'; "\n        "}; "\n        "$out -join [Environment]::NewLine }"\n    )\n    print(gpu or "N/A")\n    print()\n\n    print("=== NPU DETAILS ===")\n    npu_query = """\n$npu = Get-PnpDevice |\n    Where-Object {\n        $_.FriendlyName -and\n        $_.FriendlyName -match \'NPU|Neural|AI Boost|Intel\\\\(R\\\\) NPU\' -and\n        $_.FriendlyName -notmatch \'^USB Input Device\'\n    } |\n    Sort-Object FriendlyName -Unique\n\nif (-not $npu) {\n    \'\'\n} else {\n    $rows = foreach ($d in $npu) {\n        $drv = Get-CimInstance Win32_PnPSignedDriver |\n            Where-Object { $_.DeviceID -eq $d.InstanceId } |\n            Select-Object -First 1\n\n        $driverDate = \'N/A\'\n        $dateProp = Get-PnpDeviceProperty -InstanceId $d.InstanceId -KeyName \'DEVPKEY_Device_DriverDate\' -ErrorAction SilentlyContinue\n        if ($dateProp -and $dateProp.Data) {\n            try {\n                $driverDate = (Get-Date $dateProp.Data).ToString(\'yyyy-MM-dd\')\n            } catch {\n                $driverDate = [string]$dateProp.Data\n            }\n        } elseif ($drv -and $drv.DriverDate) {\n            try {\n                $driverDate = [Management.ManagementDateTimeConverter]::ToDateTime($drv.DriverDate).ToString(\'yyyy-MM-dd\')\n            } catch {\n                $driverDate = [string]$drv.DriverDate\n            }\n        }\n\n        "Name: $($d.FriendlyName)"\n        "DriverVersion: $(if ($drv) { $drv.DriverVersion } else { \'N/A\' })"\n        "DriverDate: $driverDate"\n        ""\n    }\n    $rows -join [Environment]::NewLine\n}\n"""\n    npu = ps(npu_query)\n    print(npu or "NPU Status: Not detected")\n\n    print("=== OPENVINO DETAILS ===")\n    print(f"Configured Location: {ov_root}")\n    setup = list(ov_root.rglob("setupvars.bat")) if ov_root.exists() else []\n    if setup:\n        sv = setup[-1]\n        print("Setupvars: Found")\n        vfile = sv.parent / "runtime" / "version.txt"\n        if vfile.is_file():\n            print(f"OpenVINO Version: {vfile.read_text(encoding=\'utf-8\', errors=\'ignore\').splitlines()[0].strip()}")\n        else:\n            print("OpenVINO Version: N/A")\n    else:\n        print("Setupvars: Missing under configured location")\n        print("OpenVINO Version: N/A")\n\n    return 0\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'


if __name__ == '__main__':
    raise SystemExit(main())
